async function verifyContinuePayment(txid, refId, addr) {
  const a3 = await sdk();
  const want = continueNote(refId, addr);
  const check = (t2) => {
    if (!t2 || t2.type !== "pay") return false;
    if (Number(t2.amount) !== CONTINUE_FEE_MICRO) return false;
    if (t2.receiver !== TREASURY_ADDR) return false;
    return t2.note === want;
  };
  try {
    const r4 = await (await algodClient()).pendingTransactionInformation(txid).do();
    const inner = r4?.txn?.txn;
    if (inner) {
      const view = {
        type: inner.type,
        amount: inner.amt,
        receiver: inner.rcv ? a3.encodeAddress(Uint8Array.from(inner.rcv)) : void 0,
        note: inner.note ? new TextDecoder().decode(Uint8Array.from(inner.note)) : void 0
      };
      if (check(view)) return true;
    }
  } catch {
  }
  try {
    const r4 = await fetch(`${INDEXER_URL}/v2/transactions/${txid}`);
    if (r4.ok) {
      const j4 = await r4.json();
      const t2 = j4.transaction;
      if (t2 && t2["tx-type"] === "pay" && t2["payment-transaction"]) {
        const view = {
          type: "pay",
          amount: t2["payment-transaction"].amount,
          receiver: t2["payment-transaction"].receiver,
          note: t2.note ? new TextDecoder().decode(Uint8Array.from(atob(t2.note), (ch) => ch.charCodeAt(0))) : void 0
        };
        return check(view);
      }
    }
  } catch {
  }
  return false;
}
