  atkCd = 0;
  // attack cooldown
  swingId = 0;
  hoverPhase = 0;
  // v15: seeded at spawn via g.rng (determinism)
  spdMul = 1;
  // v15: DESCENT wave ramp (integer-rounded at spawn)
