  // v17.0.5: juke burst direction
  // dive attack (drone)
  diveTX = 0;
  diveTY = 0;
  hitPlayer = false;
  // current swing already connected
  lieT = 0;
  lastHitId = 0;
  heldObj = null;
  // whale holding a trash can (v2)
  melee = false;
  // moltov: close bite vs molotov throw (v5)
  turnCd = 0;
  // bull: slow turning — the back stays open ~45 frames (v5)
