    this.hp = Math.ceil(this.maxHp * 0.5);
    this.lieT = 0;
    this.vx = 0;
    this.vz = 0;
    this.z = 0;
    this.flashT = 0;
    this.hitPlayer = false;
    this.invuln = 40;
    this.set("getup");
    g5.fx.ring(this.x, this.y - 8, 34, "#b45aff");
    g5.fx.ring(this.x, this.y - 8, 20, "#5a3699");
    g5.fx.popup(this.x, this.y - 66, "REVIVED", "#d89aff");
