// src/game/seal.ts
init_define_import_meta_env();
var ALGOD = "https://mainnet-api.algonode.cloud";
var MSG_MAX = 32;
var CHARSET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 !?.,:$-'/<>%()+*=_";
function cleanMsg(s4) {
  let out = "";
  for (const ch of s4.toUpperCase()) {
    if (CHARSET.indexOf(ch) >= 0) out += ch;
    if (out.length >= MSG_MAX) break;
  }
  return out;
}
function sanitizeMsg(s4) {
  return cleanMsg(s4).trim();
}
function buildNote(r4) {
  const msg = sanitizeMsg(r4.msg);
  return "GONNAFIGHT|2|" + Math.max(0, Math.floor(r4.score)) + "|" + Math.min(7, Math.max(1, Math.floor(r4.stage))) + "|" + (r4.win ? 1 : 0) + "|" + Math.max(0, Math.floor(r4.timeSec)) + "|" + Math.max(0, Math.floor(r4.deaths)) + "|" + Math.max(0, Math.floor(r4.continues)) + "|" + Math.max(0, Math.floor(r4.maxCombo)) + "|" + (r4.assetId ?? 0) + "|" + r4.skin.toLowerCase() + "|" + msg;
}
var sealDebug = { last: null };
async function pollPending(txid) {
  for (let i3 = 0; i3 < 10; i3++) {
    await new Promise((r4) => setTimeout(r4, 2e3));
    try {
      const r4 = await fetch(ALGOD + "/v2/transactions/pending/" + encodeURIComponent(txid));
      if (r4.ok) {
        const j4 = await r4.json();
        if (j4["pool-error"]) throw new Error("the network rejected the seal");
        if ((j4["confirmed-round"] ?? 0) > 0) return { status: "sealed", round: j4["confirmed-round"] };
      }
    } catch (e3) {
      if (e3 instanceof Error && e3.message === "the network rejected the seal") throw e3;
    }
  }
  return { status: "pending", round: 0 };
}
async function postSigned(blob) {
  const r4 = await fetch(ALGOD + "/v2/transactions", {
    method: "POST",
    headers: { "Content-Type": "application/x-binary" },
    body: blob
  });
  if (!r4.ok) throw new Error("algod rejected the seal (http " + r4.status + ")");
  const j4 = await r4.json();
  const txid = j4.txId ?? j4.txid;
  if (!txid) throw new Error("algod gave no txid back");
  return txid;
}
async function seal(rec) {
  const address = getWallet().address;
  if (!address) throw new Error("connect a wallet to seal");
  const note = buildNote(rec);
  const noteBytes = new TextEncoder().encode(note);
  let txid;
  let status;
  let round = 0;
  if (isMock()) {
    const fake = new Uint8Array(noteBytes.length + 7);
    fake.set(new TextEncoder().encode("MOCKSIG"), 0);
    fake.set(noteBytes, 7);
    txid = await postSigned(fake);
    const p4 = await pollPending(txid);
    status = p4.status;
    round = p4.round;
  } else {
    const algosdk = await Promise.resolve().then(() => (init_esm(), esm_exports));
    const algod = new algosdk.Algodv2("", ALGOD, "");
    const params = await algod.getTransactionParams().do();
    const txn = algosdk.makePaymentTxnWithSuggestedParamsFromObject({
      sender: address,
      receiver: SEAL_TREASURY,
      amount: 0,
      note: noteBytes,
      suggestedParams: params
    });
    let signed;
    try {
      signed = await signTransactions([
        [{ txn, signers: [address], message: "Seal your GONNA FIGHT record on-chain" }]
      ]);
    } catch {
      throw new Error("signing cancelled in the wallet");
    }
    if (!signed || signed.length === 0 || !signed[0] || signed[0].length === 0) {
      throw new Error("signing cancelled in the wallet");
    }
    try {
      const res = await algod.sendRawTransaction(signed).do();
      txid = res.txid ?? txn.txID();
    } catch {
      throw new Error("algod rejected the seal");
    }
    try {
      const p4 = await pollPending(txid);
      status = p4.status;
      round = p4.round;
    } catch {
      throw new Error("the network rejected the seal");
    }
  }
  const out = { note, txid, status, round };
  sealDebug.last = { ...out, at: Date.now() };
  return out;
}

