init_define_import_meta_env();
var FLUO4 = "#39FF14";
var PODIUM = ["#f5c542", "#c8ccd4", "#cd7f32"];
var HIST_VISIBLE = 5;
var ROW_H = 24;
var LIST_TOP = 60;
var VISIBLE = 5;
var LIST_H = VISIBLE * ROW_H;
var ROW_X = 8;
var ROW_W = VW - 16 - 24;
var TAB_WALLETS = { x: 30, y: 28, w: 150, h: 15 };
var TAB_GONNAS = { x: 204, y: 28, w: 150, h: 15 };
var HDR_Y = 46;
