    this.drawTab(ctx, TAB_WALLETS, "TOP WALLETS", this.tab === "wallets");
    this.drawTab(ctx, TAB_GONNAS, "TOP GONNAS", this.tab === "gonnas");
    this.hots.push({ ...TAB_WALLETS, id: "tab:wallets" }, { ...TAB_GONNAS, id: "tab:gonnas" });
