// src/game/arena/arenaWallet.ts
init_define_import_meta_env();
init_testnetKit();
init_arenaKit();
function arenaSession() {
  const w5 = getWallet();
  return {
    connected: w5.address !== null,
    address: w5.address,
    label: w5.address ? identityLabel(16) : "",
    accountType: mockAccountType(),
    // TODO(testnet): detect Falcon from the account
    mocked: w5.mocked
  };
}
var LS_ANON = netLsKey("gonna.arena.anon");
var LS_QA_ADDR = "gonna.qa.player.addr";
function arenaAddress() {
  if (arenaMode() === "live") {
    try {
      const qa = window.localStorage.getItem(LS_QA_ADDR);
      if (qaActive() && qa) return qa;
    } catch {
    }
    const p4 = testnetAddress();
    if (p4) return p4;
  }
  const w5 = getWallet();
  if (w5.address) return w5.address;
  try {
    let a3 = window.localStorage.getItem(LS_ANON);
    if (!a3) {
      a3 = "ANON" + Array.from(crypto.getRandomValues(new Uint8Array(24)), (b5) => "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"[b5 & 31]).join("");
      window.localStorage.setItem(LS_ANON, a3);
    }
    return a3;
  } catch {
    return "ANONDEGEN";
  }
}
async function connectArenaWallet(provider) {
  if (arenaMode() === "live") {
    const addr = await connectTestnetPera();
    if (!arenaUsesTestnetChain()) adoptExternalSession("pera", addr);
    return addr;
  }
  return connect(provider);
}
setTestnetIdentityProvider(async () => {
  if (qaActive()) {
    const address = await qaPlayerAddress();
    if (address) return { address, sign: await qaSignFn() };
  }
  const arenaAddr = testnetAddress();
  const gateAddr = isConnected() ? getWallet().address : null;
  const target = arenaAddr ?? gateAddr;
  if (!target) return null;
  const sign2 = async (groups) => {
    const arenaSign = await liveTestnetSignFn(target);
    if (arenaSign) {
      console.debug("[arena] signer chosen: arena Pera (live session)");
      try {
        return await arenaSign(groups);
      } catch (e3) {
        if (!isPeraSessionFatal(e3)) throw e3;
        console.debug("[arena] arena Pera session fatal, trying gate fallback:", e3);
      }
    }
    if (gateAddr === target && isConnected()) {
      console.debug("[arena] signer chosen: gate session fallback");
      return signTransactions(groups);
    }
    console.debug("[arena] NO live signer \u2014 WALLET NOT CONNECTED");
    throw new Error("WALLET NOT CONNECTED - TAP CONNECT");
  };
  return { address: target, sign: sign2 };
});
setSignRecoverHook(async () => {
  const ov = window.__arenaRecover;
  if (ov) return ov();
  if (qaActive()) return;
  if (arenaMode() === "live") {
    if (testnetAddress()) {
      await recoverTestnetSession();
      return;
    }
    if (isConnected()) return recoverSession();
    return;
  }
  if (isConnected()) await recoverSession();
});
function arenaPlayer(fighter) {
  const s4 = arenaSession();
  return {
    address: arenaAddress(),
    name: s4.connected ? s4.label : "YOU_DEGEN",
    score: 0,
    fighter: { ...fighter },
    accountType: s4.accountType
  };
}

