  // FNV-1a over the whole sim-relevant snapshot — twin-run determinism hash
  simHash() {
    let s4 = [
      this.score,
      this.kos,
      this.descent?.wave ?? -1,
      this.descent?.phase ?? "-",
      this.player.x.toFixed(3),
      this.player.y.toFixed(3),
      this.player.hp,
      this.player.comboHits,
      this.boss ? this.boss.kind + ":" + this.boss.hp.toFixed(1) + ":" + this.boss.x.toFixed(2) : "-"
    ].join("|");
    for (const e3 of this.enemies) {
      s4 += "|" + e3.kind + "," + e3.x.toFixed(3) + "," + e3.y.toFixed(3) + "," + e3.hp + "," + e3.state;
    }
    for (const it2 of this.items) s4 += "|i" + it2.kind + "," + it2.x.toFixed(2) + "," + it2.y.toFixed(2);
    let h5 = 2166136261;
    for (let i3 = 0; i3 < s4.length; i3++) {
      h5 ^= s4.charCodeAt(i3);
      h5 = Math.imul(h5, 16777619);
    }
    return (h5 >>> 0).toString(16).padStart(8, "0");
  }
  // CI: synchronous scripted run. tape events apply at exact frames BEFORE the
  // step; hashes sampled every 60 frames. god = the player cannot die.
  debugSim(opts) {
    if (this.scene === "intro") this.setScene("play");
    const tape = opts.tape ?? [];
    let ti = 0;
    const hashes = [];
    for (let f5 = 0; f5 < opts.frames; f5++) {
      while (ti < tape.length && tape[ti].f <= f5) {
        const ev = tape[ti++];
        if (ev.down) {
          for (const k4 of Object.keys(ev.down)) {
            this.input.down[k4] = ev.down[k4];
          }
        }
        if (ev.press) {
          for (const k4 of ev.press) this.input.pressed[k4] = true;
        }
        if (ev.cmd === "killEnemies") this.debugKillEnemies();
        else if (ev.cmd === "killNonCarrier") {
          for (const e3 of this.enemies) {
            if (e3.alive && e3.kind !== "carrier") e3.hurt({ dmg: 9999, kb: 1, down: true, dir: 1, pierce: true }, this);
          }
        } else if (ev.cmd === "killBoss") this.debugHurtBoss(99999);
      }
      if (opts.god) {
        this.player.hp = this.player.maxHp;
        if (this.player.state === "dead") {
          this.player.state = "getup";
          this.player.t = 0;
        }
      }
      this.step();
      if ((f5 + 1) % 60 === 0) hashes.push(this.simHash());
    }
    return { hashes, score: this.score, wave: this.descent?.wave ?? -1, kos: this.kos, seed: this.descent?.seedLabel ?? "" };
  }
